fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    let mut result: Vec<char> = Vec::with_capacity(s.len());

    for &ch in s.iter() {
        if ('A'..='Z').contains(&ch) {
            // ASCII uppercase to lowercase: add 32 to the code point.
            let lower = ((ch as u32) + 32) as u8 as char;
            result.push(lower);
        } else {
            result.push(ch);
        }
    }

    result
}